-- Magic staffs (Magic Staff Set by AnyRPG, CC0). Generated by scripts/build-staff-catalog.mjs.
-- Ranged like bows (server rules in db/weapons-and-archery.sql); apply with the client release.
insert into eldervale_private.realm_catalog(id,data)
select r->>0,r->1 from jsonb_array_elements('[["item:weapon:apprenticeStaff",{"name":"Apprentice staff","buy":40,"sell":12,"field":"weaponsOwned","key":"apprenticeStaff"}],["weapon:apprenticeStaff",{"name":"Apprentice staff","desc":"A crooked staff set with a green focus gem. Magic range 10 · Attack +9 · Damage +5 · Attack turn 2.4s.","kind":"staff","damage":5,"attack":9,"speed":2.4,"reach":10,"twoHanded":true,"ranged":true,"magic":true}],["item:weapon:sapphireStaff",{"name":"Sapphire staff","buy":160,"sell":48,"field":"weaponsOwned","key":"sapphireStaff"}],["weapon:sapphireStaff",{"name":"Sapphire staff","desc":"A staff crowned with a deep blue sapphire. Magic range 11 · Attack +14 · Damage +9 · Attack turn 2.4s.","kind":"staff","damage":9,"attack":14,"speed":2.4,"reach":11,"twoHanded":true,"ranged":true,"magic":true}],["item:weapon:amethystStaff",{"name":"Amethyst staff","buy":220,"sell":66,"field":"weaponsOwned","key":"amethystStaff"}],["weapon:amethystStaff",{"name":"Amethyst staff","desc":"A staff holding a humming amethyst. Magic range 11 · Attack +16 · Damage +11 · Attack turn 2.5s.","kind":"staff","damage":11,"attack":16,"speed":2.5,"reach":11,"twoHanded":true,"ranged":true,"magic":true}],["item:weapon:emberStaff",{"name":"Ember staff","buy":300,"sell":90,"field":"weaponsOwned","key":"emberStaff"}],["weapon:emberStaff",{"name":"Ember staff","desc":"A staff whose ruby burns like a coal. Magic range 10 · Attack +18 · Damage +13 · Attack turn 2.6s.","kind":"staff","damage":13,"attack":18,"speed":2.6,"reach":10,"twoHanded":true,"ranged":true,"magic":true}]]'::jsonb) r
on conflict (id) do update set data=excluded.data;
insert into eldervale_private.shop_stock(merchant,item,buy,sell,stock,target_stock)
select s.merchant::uuid,s.item,(c.data->>'buy')::int,(c.data->>'sell')::int,-1,null
from (values ('9c32d3de-8fee-4e11-af51-9bc84d7fbb46','weapon:apprenticeStaff'),('4b178de6-0fcb-47d4-9587-40cb9254745e','weapon:amethystStaff'),('f2365884-03c8-43b6-aa2d-8df745319bbe','weapon:emberStaff'),('36b9aa48-81f4-44bf-b934-dbc4ec8f1a08','weapon:sapphireStaff'),('36b9aa48-81f4-44bf-b934-dbc4ec8f1a08','weapon:emberStaff')) s(merchant,item) join eldervale_private.realm_catalog c on c.id='item:'||s.item
on conflict (merchant,item) do update set buy=excluded.buy,sell=excluded.sell,stock=-1,target_stock=null;
